SELECT lease_epoch
FROM research_task
WHERE id = #{taskId} AND status = 'RUNNING' AND lease_owner = #{leaseOwner}

mapper.update:
UPDATE research_task
SET event_sequence = event_sequence + 1, updated_at = #{now}
WHERE id = #{taskId} AND status = 'RUNNING'
  AND lease_owner = #{leaseOwner} AND lease_epoch = #{leaseEpoch}

UPDATE research_task
SET stage = #{stage}, turn_count = #{turnCount}, tool_call_count = #{toolCallCount},
    heartbeat_at = #{now}, lease_until = #{leaseUntil}, updated_at = #{now}
WHERE id = #{taskId} AND status = 'RUNNING' AND lease_owner = #{leaseOwner}

UPDATE research_task
SET stage = #{stage}, turn_count = #{turnCount}, tool_call_count = #{toolCallCount},
    heartbeat_at = #{now}, lease_until = #{leaseUntil}, updated_at = #{now}
WHERE id = #{taskId} AND status = 'RUNNING'
  AND lease_owner = #{leaseOwner} AND lease_epoch = #{leaseEpoch}

UPDATE research_task
SET status = #{status}, stage = #{stage}, stop_reason = #{stopReason}, last_error = #{error},
    heartbeat_at = #{now}, completed_at = #{now}, lease_owner = NULL, lease_until = NULL,
    updated_at = #{now}
WHERE id = #{taskId}

UPDATE research_task
SET status = #{status}, stage = #{stage}, stop_reason = #{stopReason}, last_error = #{error},
    heartbeat_at = #{now}, completed_at = #{now}, lease_owner = NULL, lease_until = NULL,
    updated_at = #{now}
WHERE id = #{taskId} AND status = 'RUNNING'
  AND lease_owner = #{leaseOwner} AND lease_epoch = #{leaseEpoch}

