SELECT id, thread_id, query, search_mode, status, revision_number, created_at, updated_at
FROM research_task

    owner_id = #{ownerId}
    AND status = #{status}

        AND (
          CAST(id AS CHAR) LIKE CONCAT('%', #{keyword}, '%')
          OR query LIKE CONCAT('%', #{keyword}, '%')
          OR thread_id LIKE CONCAT('%', #{keyword}, '%')
          OR request_payload LIKE CONCAT('%', #{keyword}, '%')
        )


ORDER BY updated_at DESC, id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM research_task

    owner_id = #{ownerId}
    AND status = #{status}

        AND (
          CAST(id AS CHAR) LIKE CONCAT('%', #{keyword}, '%')
          OR query LIKE CONCAT('%', #{keyword}, '%')
          OR thread_id LIKE CONCAT('%', #{keyword}, '%')
          OR request_payload LIKE CONCAT('%', #{keyword}, '%')
        )

